function omitFields<T extends object, K extends keyof T>(item: T, keys: readonly K[]): Omit<T, K> {
  const copy = { ...item };
  for (const key of keys) delete copy[key];
  return copy;
}

const user = { id: "U-7", name: "Ada", passwordHash: "(hash)", resetToken: "abc123" };
