questions.solution:
function counted<F extends (...args: any[]) => any>(fn: F): { call: (...args: Parameters<F>) => ReturnType<F>; calls: () => number } {
  let count = 0;
  return {
    call: (...args) => {
      count += 1;
      return fn(...args);
    },
    calls: () => count,
  };
}

const vat = counted((kobo: number) => Math.round(kobo * 0.075));
console.log(vat.call(100_000), vat.call(40_000), "calls:", vat.calls());

